SELECT subject_key,occurrence_ms,effective_due_ms FROM (SELECT s.automation_id AS subject_key,CASE WHEN unixepoch(s.next_due_at) IS NULL OR abs(unixepoch(s.next_due_at)*1000+CAST(substr(strftime('%f',s.next_due_at),4,3) AS INTEGER))>9223372036854 THEN 0 ELSE unixepoch(s.next_due_at)*1000+CAST(substr(strftime('%f',s.next_due_at),4,3) AS INTEGER) END AS occurrence_ms,CASE WHEN a.attempt_id IS NOT NULL THEN CASE WHEN a.state='failing' AND a.last_failure IN ('corrupt_row','constraint_violated','statement_rejected','refused','other_store_unavailable') THEN CASE WHEN unixepoch(a.next_try_at) IS NULL OR abs(unixepoch(a.next_try_at)*1000+CAST(substr(strftime('%f',a.next_try_at),4,3) AS INTEGER))>9223372036854 THEN 0 ELSE unixepoch(a.next_try_at)*1000+CAST(substr(strftime('%f',a.next_try_at),4,3) AS INTEGER) END ELSE 0 END WHEN s.state!='active' THEN 0 ELSE CASE WHEN unixepoch(s.next_due_at) IS NULL OR abs(unixepoch(s.next_due_at)*1000+CAST(substr(strftime('%f',s.next_due_at),4,3) AS INTEGER))>9223372036854 THEN 0 ELSE unixepoch(s.next_due_at)*1000+CAST(substr(strftime('%f',s.next_due_at),4,3) AS INTEGER) END END AS effective_due_ms FROM automation_schedules s LEFT JOIN engine_work_attempts a ON a.machine_kind='automation_timer' AND a.subject_key=s.automation_id WHERE s.state NOT IN ('done','disabled') AND (1) AND NOT(COALESCE(a.state,'')='retired' AND a.last_failure IN ('corrupt_row','constraint_violated','statement_rejected','refused','other_store_unavailable'))) WHERE effective_due_ms<=?1 ORDER BY effective_due_ms,subject_key LIMIT ?2
